import sys,json
try:
    d=json.loads(sys.stdin.read())
    if 'runs' in d:
        runs = d['runs']
        print(f'Total runs: {len(runs)}')
        ok = sum(1 for r in runs if r.get('status') == 'ok')
        failed = sum(1 for r in runs if r.get('status') == 'failed')
